   477		entries: SessionEntry[],
   478		leafId?: string | null,
   479		byId?: Map<string, SessionEntry>,
   480	): SessionEntry[] {
   481		const path = buildSessionPath(entries, leafId, byId);
   482		let compaction: CompactionEntry | null = null;
   483	
   484		for (const entry of path) {
   485			if (entry.type === "compaction") {
   486				compaction = entry;
   487			}
   488		}
   489	
   490		if (!compaction) {
   491			return path;
   492		}
   493	
   494		const compactionIdx = path.findIndex((entry) => entry.id === compaction.id);
   495		if (compactionIdx < 0) {
   496			return path;
   497		}
   498	
   499		const contextEntries: SessionEntry[] = [compaction];
   500		let foundFirstKept = false;
   501		for (let i = 0; i < compactionIdx; i++) {
   502			const entry = path[i];
   503			if (entry.id === compaction.firstKeptEntryId) {
   504				foundFirstKept = true;
   505			}
   506			if (foundFirstKept && !(entry.type === "message" && entry.message.role === "system")) {
