python - <<'PY'
import json,collections,subprocess
m=json.load(open('/tmp/candidate.json'))['diagrams'][0]['mappings']; d=collections.defaultdict(set)
for x in m:d[x['path']].update(range(x['startLine'],x['endLine']+1))
for f,lines in d.items():
 text=open(f).read().splitlines(); print(f,len(lines),'selected',len(lines & set(range(1,len(text)+1))) if False else len(lines))
 for i in sorted(lines):
  assert 1<=i<=len(text),(f,i)
  line=text[i-1].strip()
  if i==min(lines) or i-1 not in lines:print('  START',i,line[:110])
  if i==max(lines) or i+1 not in lines:print('  END  ',i,line[:110])
PY

